import { useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import type { Person } from '../people/people';
import { SIGNED_AMOUNT, claimsKey, useClaims } from './claims';
import type { Claim, ClaimInput } from './claims';
import { useOneAtATime } from '../../query/useOneAtATime';
import { setClaimError, useClaimError } from './claimError';
import { contains, usePeriods } from '../periods/periods';
import { useSettings } from '../settings/settings';
import { useSheetToday } from '../session/sheetToday';
import { tagsKey } from '../tags/tags';
import { useTemplates } from '../templates/templates';

const EMPTY: ClaimInput = { amount: '', date: '', note: '', corrects: '', ref: '', tags: '' };

// A person's claims, newest first, and the form that adds one — or, while a claim's editor is
// open, saves that claim's changes. Opening an editor (the edit button) locks the claim for every
// other user and fills the form with the claim's values; a refusal (not editable, a viewer, or
// locked by another user) shows as the claim's error. Saving or cancelling the editor releases the
// lock. A claim the signed-in user holds the lock on comes back with its editor open when the sheet
// is loaded again. A refusal the screen can see (not a DRAFT, due by a date in a closed period, a viewer, locked
// by another user) shows at once; otherwise the editor opens at once and the lock is taken behind it —
// a save waits for it, and a refused lock closes the editor and shows the claim's error.
export function PersonClaims({ person }: { person: Person }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const claims = (useClaims().data ?? []).filter((c) => c.personId === person.id);
  const [form, setForm] = useState<ClaimInput>(EMPTY);
  const [editing, setEditing] = useState<number | undefined>(undefined);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();
  const periods = usePeriods().data ?? [];
  const settings = useSettings().data;
  const today = useSheetToday();
  // A viewer refused editing, unless a delegation in force on the sheet's today makes them a steward.
  const viewer =
    (settings?.roles ?? []).some((r) => r.user === user && r.role === 'viewer') &&
    !(settings?.delegations ?? []).some((d) => d.user === user && d.from <= today && today <= d.to);
  const editingNow = useRef<number | undefined>(undefined);
  editingNow.current = editing;
  const locking = useRef<Promise<void>>(Promise.resolve());
  const templates = useTemplates().data ?? [];
  const [template, setTemplate] = useState('');

  const claimsUrl = `/api/sheets/${encodeURIComponent(sheet)}/claims`;

  // Show the claim as (un)locked by the user at once, so a released lock does not re-open its editor.
  const markLocked = (id: number, lockedBy: string | null) =>
    queryClient.setQueryData<Claim[]>(claimsKey(sheet), (all) => all?.map((c) => (c.id === id ? { ...c, lockedBy } : c)));

  const release = (id: number) => {
    markLocked(id, null);
    postJson<Claim>(`${claimsUrl}/${id}/unlock?user=${encodeURIComponent(user)}`, {}).catch(() => undefined);
  };

  const close = () => {
    if (editing !== undefined) release(editing);
    setEditing(undefined);
    setForm(EMPTY);
    setError('');
  };

  const fill = (c: Claim) => {
    setEditing(c.id);
    setForm({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '', ref: c.ref ?? '', tags: c.tags.join(', ') });
    setError('');
  };

  const save = useMutation({
    mutationFn: async (input: ClaimInput) => {
      if (editing === undefined) {
        return postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/claims?user=${encodeURIComponent(user)}`, input);
      }
      await locking.current;
      return putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${editing}?user=${encodeURIComponent(user)}`, input);
    },
    onSuccess: async () => {
      if (editing !== undefined) markLocked(editing, null);
      setEditing(undefined);
      setForm(EMPTY);
      setError('');
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: tagsKey(sheet) }),
      ]);
    },
    onError: () => setError('That claim could not be saved.'),
  });

  // A DRAFT claim from the chosen template: its amount and note as they are now, with no date, by the claim form's
  // rules; a refusal shows as the claim form's error.
  const fromTemplate = useMutation({
    mutationFn: (name: string) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/template-claims?user=${encodeURIComponent(user)}`,
        { template: name },
      ),
    onSuccess: async () => {
      setError('');
      await Promise.all([
        queryClient.invalidateQueries({ queryKey: claimsKey(sheet) }),
        queryClient.invalidateQueries({ queryKey: tagsKey(sheet) }),
      ]);
    },
    onError: () => setError('A claim could not be added from that template.'),
  });

  const addFromTemplate = () => {
    setError('');
    if (!template) {
      setError('Choose a claim template.');
      return;
    }
    once(() => fromTemplate.mutateAsync(template));
  };

  const refused = (c: Claim) =>
    `This ${c.status} claim cannot be edited (only a DRAFT not due in a closed period, not by a viewer, nor while another user is editing it).`;

  // Why the edit button is refused, from what the screen holds; '' when the server is asked.
  const refusal = (c: Claim) =>
    c.status !== 'DRAFT' ||
    viewer ||
    (c.lockedBy !== null && c.lockedBy !== user) ||
    periods.some((p) => p.closed && contains(p, c.dueBy))
      ? refused(c)
      : '';

  // Re-open the editor of a claim the user still holds the lock on (the sheet was loaded again).
  const held = editing === undefined ? claims.find((c) => c.lockedBy === user) : undefined;
  useEffect(() => {
    if (held) fill(held);
  }, [held?.id]);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!SIGNED_AMOUNT.test(form.amount.trim())) {
      setError('Type an amount with at most two decimals.');
      return;
    }
    const date = form.date.trim();
    if (date && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      setError('Type a date as yyyy-mm-dd.');
      return;
    }
    once(() => save.mutateAsync(form));
  };

  const change = (patch: Partial<ClaimInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  const edit = (c: Claim) => {
    const why = refusal(c);
    setClaimError(sheet, c.id, why);
    if (why) return;
    if (editing !== undefined) release(editing);
    markLocked(c.id, user);
    fill(c);
    const taken = postJson<Claim>(`${claimsUrl}/${c.id}/lock?user=${encodeURIComponent(user)}`, {}).then(
      () => undefined,
      async (e) => {
        markLocked(c.id, null);
        if (editingNow.current === c.id) {
          setEditing(undefined);
          setForm(EMPTY);
          setError('');
        }
        setClaimError(sheet, c.id, refused(c));
        await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
        throw e;
      },
    );
    taken.catch(() => undefined);
    locking.current = taken;
  };

  return (
    <td data-testid="person-claims">
      <ul>
        {claims.map((c) => (
          <li key={c.id} data-testid={`claim-row-${c.id}`}>
            <span data-testid="claim-amount">{c.amount}</span> <span data-testid="claim-date">{c.date}</span>{' '}
            <span data-testid="claim-note" style={{ whiteSpace: 'pre' }}>
              {c.note}
            </span>{' '}
            <ClaimRowValues.Slot claim={c} person={person} />{' '}
            {editing === c.id ? (
              <button type="button" data-testid="claim-cancel" onClick={close}>
                Cancel
              </button>
            ) : (
              <button type="button" data-testid="claim-edit" onClick={() => edit(c)}>
                Edit
              </button>
            )}{' '}
            <ClaimInlineAmount claim={c} refusal={refusal(c)} />
          </li>
        ))}
      </ul>
      <form onSubmit={submit} data-testid="claim-form">
        <input
          data-testid="claim-form-amount"
          placeholder="Amount"
          value={form.amount}
          onChange={(e) => change({ amount: e.target.value })}
        />
        <input
          data-testid="claim-form-date"
          placeholder="yyyy-mm-dd"
          value={form.date}
          onChange={(e) => change({ date: e.target.value })}
        />
        <input
          data-testid="claim-form-note"
          placeholder="Note"
          value={form.note}
          onChange={(e) => change({ note: e.target.value })}
        />
        <input
          data-testid="claim-form-corrects"
          placeholder="Corrects claim no."
          value={form.corrects}
          onChange={(e) => change({ corrects: e.target.value })}
        />
        <input
          data-testid="claim-form-ref"
          placeholder="Reference"
          value={form.ref}
          onChange={(e) => change({ ref: e.target.value })}
        />
        <input
          data-testid="claim-form-tags"
          placeholder="Tags, comma separated"
          value={form.tags}
          onChange={(e) => change({ tags: e.target.value })}
        />
        <button type="submit" data-testid="claim-form-submit" disabled={save.isPending}>
          {editing === undefined ? 'Add claim' : 'Save claim'}
        </button>
        <select
          data-testid="claim-template-select"
          value={template}
          onChange={(e) => {
            setTemplate(e.target.value);
            setError('');
          }}
        >
          <option value="">Template…</option>
          {templates.map((t) => (
            <option key={t.name} value={t.name}>
              {t.name}
            </option>
          ))}
        </select>
        <button type="button" data-testid="claim-template-add" disabled={fromTemplate.isPending} onClick={addFromTemplate}>
          Add from template
        </button>
        {error && <span data-testid="claim-form-error">{error}</span>}
      </form>
    </td>
  );
}

// A claim's amount changed in its row: the entry and save button beside the edit button. The save is
// the editor's save with only the amount changed, so it follows the claim form's rules (and writes
// CLAIM_EDITED); a refusal shows as the claim's error, at once when the screen can see it.
function ClaimInlineAmount({ claim, refusal }: { claim: Claim; refusal: string }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setError] = useClaimError(claim.id);
  const [amount, setAmount] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const save = useMutation({
    mutationFn: (value: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}?user=${encodeURIComponent(user)}`, {
        amount: value,
        date: claim.date,
        note: claim.note,
        corrects: claim.corrects ?? '',
        ref: claim.ref ?? '',
        tags: claim.tags.join(','),
      }),
    onSuccess: async () => {
      setAmount('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () => setError('That claim could not be saved.'),
  });

  return (
    <>
      <input
        data-testid="claim-inline-amount"
        placeholder="Amount"
        value={amount}
        onChange={(e) => {
          setAmount(e.target.value);
          setError('');
        }}
      />
      <button
        type="button"
        data-testid="claim-inline-save"
        disabled={save.isPending}
        onClick={() => {
          setError('');
          if (refusal) {
            setError(refusal);
            return;
          }
          const value = amount.trim();
          if (!SIGNED_AMOUNT.test(value)) {
            setError('Type an amount with at most two decimals.');
            return;
          }
          once(() => save.mutateAsync(value));
        }}
      >
        Save amount
      </button>
    </>
  );
}
import type { Claim } from './claims';

// A claim's number on the sheet; empty while it is a draft; a voided claim keeps it.
export function ClaimNumber({ claim }: { claim: Claim }) {
  return <span data-testid="claim-number">{claim.number ?? ''}</span>;
}
import { ClaimRowValues } from '../../slots/defs/claimRow';
import { ClaimNumber } from './ClaimNumber';

export const contribution = ClaimRowValues.fill({ order: 15, Component: ClaimNumber });
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople } from '../people/people';
import type { Claim } from './claims';
import { AMOUNT, claimsKey } from './claims';
import { useOneAtATime } from '../../query/useOneAtATime';
import { useClaimError } from './claimError';
import { useVoidReasons } from '../voidreasons/voidReasons';

type Action = 'open' | 'settle' | 'approve' | 'reject' | 'void' | 'resettle' | 'delete' | 'restore';

const ACTIONS: Array<{ action: Action; label: string }> = [
  { action: 'open', label: 'Open' },
  { action: 'settle', label: 'Settle' },
  { action: 'approve', label: 'Approve' },
  { action: 'reject', label: 'Reject' },
  { action: 'void', label: 'Void' },
  { action: 'resettle', label: 'Re-settle' },
  { action: 'delete', label: 'Delete' },
  { action: 'restore', label: 'Restore' },
];

const REFUSED: Partial<Record<Action, string>> = {
  open: ' (your role may not be allowed to open a claim)',
  settle: ' (the user who opened it cannot settle it, one whose due is above the proof threshold needs a proof, and your role may not be allowed to settle)',
  void: ' (your role may not be allowed to void a claim; only a steward voids a settled claim, within 7 days of its settlement; while the sheet has void reasons, choose one)',
  approve: ' (only a steward approves a pending claim, and not the user who opened it; one whose due is above the proof threshold needs a proof)',
  reject: ' (only a steward rejects a pending claim, and a reason is required)',
  resettle: ' (only a steward re-settles a settled claim)',
  delete: ' (only a DRAFT claim not due in a closed period is deleted)',
  restore: ' (a deleted claim is restored only on the day it was deleted)',
};

// A claim's status and the buttons that change it. Every button is shown; the server refuses a
// change the status does not allow, and the refusal shows as the claim's error. A clerk's settle
// above the clerk limit makes the claim PENDING; a reject sends the reason typed beside it. A role
// allowed to reassign (standing rule: a steward) moves a DRAFT, OPEN or PENDING claim to the person chosen beside the
// Move button. A steward re-settles a SETTLED claim, freezing it again at today's figure. An OPEN claim is deferred to the
// date typed beside the Defer button. The Add proof button raises the claim's proofs count by one (not on a
// SETTLED or VOID claim, nor one due by a date in a closed period). The Split button splits the amount typed beside it off an
// OPEN claim into a new OPEN claim of the same person (more than 0.00 and less than the claim's amount). A steward
// re-dates an OPEN or PENDING claim to the date typed beside the Re-date button. While the sheet has void reasons, a void
// sends the reason chosen beside it (none chosen: the server refuses it). Delete sets a DRAFT claim aside as DELETED;
// Restore makes it a DRAFT again, only on the sheet's today it was deleted.
export function ClaimStatus({ claim }: { claim: Claim }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [error, setError] = useClaimError(claim.id);
  const [reason, setReason] = useState('');
  const [voidReason, setVoidReason] = useState('');
  const voidReasons = useVoidReasons().data ?? [];
  const [moveTo, setMoveTo] = useState('');
  const [deferTo, setDeferTo] = useState('');
  const [splitAmount, setSplitAmount] = useState('');
  const [redateTo, setRedateTo] = useState('');
  const others = (usePeople().data ?? []).filter((p) => p.id !== claim.personId);
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const change = useMutation({
    mutationFn: (action: Action) =>
      postJson<Claim>(
        `/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/${action}?user=${encodeURIComponent(user)}`,
        action === 'reject' ? { reason } : action === 'void' ? { reason: voidReason } : {},
      ),
    onSuccess: async (_c, action) => {
      if (action === 'reject') setReason('');
      if (action === 'void') setVoidReason('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: (_e, action) => setError(`This ${claim.status} claim cannot be changed by ${action}${REFUSED[action] ?? ''}.`),
  });

  const reassign = useMutation({
    mutationFn: (personId: number) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/person?user=${encodeURIComponent(user)}`, {
        personId,
      }),
    onSuccess: async () => {
      setMoveTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(`This ${claim.status} claim cannot be moved (only a DRAFT, OPEN or PENDING claim is moved, by a role allowed to reassign).`),
  });

  const defer = useMutation({
    mutationFn: (until: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/deferral?user=${encodeURIComponent(user)}`, {
        until,
      }),
    onSuccess: async () => {
      setDeferTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(`This ${claim.status} claim cannot be deferred to that date (only an OPEN claim, to a date after today, outside a closed period).`),
  });

  const split = useMutation({
    mutationFn: (amount: string) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/split?user=${encodeURIComponent(user)}`, {
        amount,
      }),
    onSuccess: async () => {
      setSplitAmount('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(
        `This ${claim.status} claim cannot be split by that amount (only an OPEN claim, not deferred nor in a closed period, by more than 0.00 and less than its amount, by a role allowed to open a claim).`,
      ),
  });

  const redate = useMutation({
    mutationFn: (date: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/date?user=${encodeURIComponent(user)}`, {
        date,
      }),
    onSuccess: async () => {
      setRedateTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(
        `This ${claim.status} claim cannot be re-dated to that date (only a steward re-dates an OPEN or PENDING claim, not after its person's retirement, nor one due by a date in a closed period).`,
      ),
  });

  const proof = useMutation({
    mutationFn: () =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/proofs?user=${encodeURIComponent(user)}`, {}),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(`This ${claim.status} claim cannot be given a proof (not a SETTLED or VOID claim, nor one in a closed period).`),
  });

  return (
    <>
      <span data-testid="claim-status">{claim.status}</span>{' '}
      {ACTIONS.map(({ action, label }) => (
        <button
          key={action}
          type="button"
          data-testid={`claim-${action}`}
          disabled={change.isPending}
          onClick={() => {
            setError('');
            once(() => change.mutateAsync(action));
          }}
        >
          {label}
        </button>
      ))}
      <input
        data-testid="claim-reject-reason"
        aria-label="Reject reason"
        placeholder="reason"
        value={reason}
        onChange={(e) => {
          setReason(e.target.value);
          setError('');
        }}
      />
      {voidReasons.length > 0 && (
        <select
          data-testid="claim-void-reason"
          aria-label="Void reason"
          value={voidReason}
          onChange={(e) => {
            setVoidReason(e.target.value);
            setError('');
          }}
        >
          <option value="">void reason…</option>
          {voidReasons.map((r) => (
            <option key={r} value={r}>
              {r}
            </option>
          ))}
        </select>
      )}
      <select
        data-testid="claim-reassign-to"
        aria-label="Move to"
        value={moveTo}
        onChange={(e) => {
          setMoveTo(e.target.value);
          setError('');
        }}
      >
        <option value="">move to…</option>
        {others.map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>
      <button
        type="button"
        data-testid="claim-reassign"
        disabled={reassign.isPending}
        onClick={() => {
          setError('');
          if (!moveTo) {
